const {app,BrowserWindow}=require('electron');const assert=require('node:assert/strict');const {join,dirname}=require('node:path');const fs=require('node:fs');const index=process.argv[2];app.setPath('userData',join(dirname(index),'profile'));
app.whenReady().then(async()=>{const win=new BrowserWindow({show:false,width:1280,height:900,webPreferences:{nodeIntegration:false,contextIsolation:true,sandbox:true}});await win.loadFile(index);const run=code=>win.webContents.executeJavaScript(code);const until=async code=>{for(let i=0;i<350;i++){if(await run(code))return;await new Promise(r=>setTimeout(r,20));}throw Error(code+' '+await run('document.body.innerText'));};const menu=async(index=0,search=false,keyboard=false)=>{await run(`(()=>{const row=document.querySelectorAll('${search?'.mail-search-subject':'.mail-message-row'}')[${index}];row.focus();${keyboard?"row.dispatchEvent(new KeyboardEvent('keydown',{key:'F10',shiftKey:true,bubbles:true,cancelable:true}))":"row.dispatchEvent(new MouseEvent('contextmenu',{bubbles:true,cancelable:true,clientX:380,clientY:230}))"}})()`);await until("!!document.querySelector('[role=menu]')&&document.querySelector('[role=menu]').textContent.includes('Mark read')");};const escape=async()=>{win.webContents.sendInputEvent({type:'keyDown',keyCode:'Escape'});win.webContents.sendInputEvent({type:'keyUp',keyCode:'Escape'});await until("!document.querySelector('[role=menu]')");};
 await until("document.querySelectorAll('.mail-message-row').length>5");
 await run("document.querySelectorAll('.mail-message-select-row>input')[0].click();document.querySelectorAll('.mail-message-select-row>input')[1].click()");await menu(0);assert.equal(await run("document.querySelector('[role=menu]').textContent.includes('2 messages')"),true);assert.equal(await run("[...document.querySelectorAll('[role=menuitem]')].some(e=>e.textContent==='Reply')"),false);fs.writeFileSync(join(dirname(index),'mailbox.png'),(await win.webContents.capturePage()).toPNG());
 await run("[...document.querySelectorAll('[role=menuitem]')].find(e=>e.textContent.startsWith('Mark read')).click()");await until("!document.querySelector('[role=menu]')");await until("document.body.textContent.includes('Undo available')&&!!document.querySelector('.mail-action-error')");await run("document.querySelector('[aria-label=\"Undo Mark read\"]').click()");await until("document.body.textContent.includes('Cancelled')");
 await menu(4,false,true);assert.equal(await run("document.querySelectorAll('.mail-message-select-row>input:checked').length"),1);await escape();assert.equal(await run("document.activeElement===document.querySelectorAll('.mail-message-row')[4]"),true);
 await menu(4);await run("window.staleAction=[...document.querySelectorAll('[role=menuitem]')].find(e=>e.textContent.startsWith('Mark unread'));document.querySelectorAll('.mail-message-row')[6].click()");await until("!document.querySelector('[role=menu]')");await run("window.staleAction.click()");
 await menu(4);await run("[...document.querySelectorAll('[role=menuitem]')].find(e=>e.textContent==='Permanently delete…').click()");await until("!!document.querySelector('[role=dialog]')");assert.equal(await run("document.querySelector('[role=dialog]').textContent.includes('cannot be undone')"),true);await run("[...document.querySelectorAll('[role=dialog] button')].find(e=>e.textContent==='Cancel').click()");await until("!document.querySelector('[role=dialog]')");
 await run("document.querySelector('.mail-message-scroll').scrollTop=80;window.oldScroll=document.querySelector('.mail-message-scroll').scrollTop;document.querySelectorAll('.mail-message-row')[4].dispatchEvent(new MouseEvent('click',{ctrlKey:true,bubbles:true,cancelable:true,clientX:380,clientY:230}))");await until("!!document.querySelector('[role=menu]')");await escape();assert.equal(await run("document.querySelector('.mail-message-scroll').scrollTop===window.oldScroll"),true);
 await menu(4);win.webContents.sendInputEvent({type:'mouseDown',x:1100,y:700,button:'left',clickCount:1});win.webContents.sendInputEvent({type:'mouseUp',x:1100,y:700,button:'left',clickCount:1});await until("!document.querySelector('[role=menu]')");
 await run("window.beforeRows=document.querySelectorAll('.mail-message-row').length;[...document.querySelectorAll('.mail-pagination button')][0].click()");await until("document.querySelectorAll('.mail-message-row').length===2");await menu(0,false,true);await escape();
 await run("(()=>{const input=document.querySelector('[aria-label=\"Search mail\"]');Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value').set.call(input,'contract');input.dispatchEvent(new Event('input',{bubbles:true}));})()");await until("document.querySelectorAll('.mail-search-subject').length===3");
 await run("document.querySelectorAll('.mail-search-hit>input')[0].click()");await until("!document.querySelector('.mail-search-hit>input').disabled");await run("document.querySelectorAll('.mail-search-hit>input')[1].click()");await until("!document.querySelector('.mail-search-hit>input').disabled");await menu(1,true,true);assert.equal(await run("document.querySelector('[role=menu]').textContent.includes('2 messages · multiple accounts')"),true);assert.equal(await run("[...document.querySelectorAll('[role=menuitem]')].find(e=>e.textContent.includes('Move')&&e.textContent.includes('…')).getAttribute('aria-disabled')"),'true');fs.writeFileSync(join(dirname(index),'search.png'),(await win.webContents.capturePage()).toPNG());await escape();
 await menu(2,true);assert.equal(await run("document.querySelector('[role=menu]').textContent.includes('Local archives are read-only')"),true);assert.equal(await run("[...document.querySelectorAll('[role=menuitem]')].find(e=>e.textContent.startsWith('Mark read')).getAttribute('aria-disabled')"),'true');await escape();
 console.log('CONTEXT_PASS');win.destroy();app.quit();}).catch(error=>{console.error(error);app.exit(1)});
